export function renderFrameComanda(){
    console.log("Imprimiendo comanda desde utils/printcomandas.js...");
    // Crear o mostrar el contenedor del PDF
    let pdfContainer = document.getElementById('pdfPreviewContainer');
    if (!pdfContainer) {
        pdfContainer = document.createElement('div');
        pdfContainer.id = 'pdfPreviewContainer';
        pdfContainer.style.position = 'fixed';
        pdfContainer.style.top = '0';
        pdfContainer.style.left = '0';
        pdfContainer.style.width = '100%';
        pdfContainer.style.height = '100%';
        //pdfContainer.style.height = 'auto';
        pdfContainer.style.backgroundColor = 'rgba(0,0,0,0.8)';
        pdfContainer.style.zIndex = '9999';
        pdfContainer.style.display = 'flex';
        pdfContainer.style.justifyContent = 'center';
        pdfContainer.style.alignItems = 'center';
        
        // Crear iframe para mostrar el PDF
        const iframe = document.createElement('iframe');
        iframe.id = 'pdfIframe';
        iframe.style.width = '80%';
        iframe.style.height = '90%';
        //iframe.style.height = 'auto';
        iframe.style.border = 'none';
        iframe.style.borderRadius = '8px';
        iframe.style.backgroundColor = '#fff';
        
        // Botón para cerrar
        const closeBtn = document.createElement('button');
        closeBtn.innerHTML = '&times;';
        closeBtn.style.position = 'absolute';
        closeBtn.style.top = '20px';
        closeBtn.style.right = '20px';
        closeBtn.style.background = '#ff4444';
        closeBtn.style.color = 'white';
        closeBtn.style.border = 'none';
        closeBtn.style.borderRadius = '50%';
        closeBtn.style.width = '40px';
        closeBtn.style.height = '40px';
        closeBtn.style.fontSize = '20px';
        closeBtn.style.cursor = 'pointer';
        closeBtn.onclick = function() {
            document.body.removeChild(pdfContainer);
        };
        
        // Botón para imprimir
        const printBtn = document.createElement('button');
        printBtn.innerHTML = 'Imprimir';
        printBtn.style.position = 'absolute';
        printBtn.style.bottom = '20px';
        // colocamos los botones lado a lado al centro
        printBtn.style.left = '50%';
        printBtn.style.transform = 'translateX(-110%)';
        printBtn.style.padding = '10px 20px';
        printBtn.style.background = '#4CAF50';
        printBtn.style.color = 'white';
        printBtn.style.border = 'none';
        printBtn.style.borderRadius = '4px';
        printBtn.style.cursor = 'pointer';
        printBtn.onclick = function() {
            iframe.contentWindow.print();
        };
        
        // Botón para compartir por WhatsApp
        const shareBtn = document.createElement('button');
        shareBtn.innerHTML = 'Compartir WhatsApp';
        shareBtn.style.position = 'absolute';
        shareBtn.style.bottom = '20px';
        shareBtn.style.left = '50%';
        shareBtn.style.transform = 'translateX(10%)';
        shareBtn.style.padding = '10px 20px';
        shareBtn.style.background = '#25D366';
        shareBtn.style.color = 'white';
        shareBtn.style.border = 'none';
        shareBtn.style.borderRadius = '4px';
        shareBtn.style.cursor = 'pointer';
        shareBtn.onclick = function() {
            try {
                const data = window.currentComandaData || null;
                if (!data) {
                    alert('No se encontró la información de la comanda para compartir.');
                    return;
                }
                // Número de WhatsApp configurado (déjelo en null para usar el del cliente si existe)
                const configuredNumber = null;
                const configuredPrefijo = null;
                const header = `*Pedido # ${data.nro_pedido}*`;
                //const negocio = `${data.nombre_restaurant} - ${data.sucursal}`;
                const cliente = (data.datosCliente && data.datosCliente.nombre_completo) ? `Cliente: ${data.datosCliente.nombre_completo}` : '';
                const fecha = 'Fecha: '+data.fecha_atencion;
                const fechaHora = new Date(data.fecha_atencion+' '+data.hora_atencion);
                const hora = 'Hora: '+fechaHora.toLocaleTimeString('es-ES', {hour: '2-digit', minute:'2-digit'});
                // Resolver número destino: configuración -> celular del cliente -> teléfono del cliente -> campo alterno
                var toNumber = configuredNumber;
                var prefijo = configuredPrefijo;

                if (data.numero_whatsapp) {
                    toNumber = data.numero_whatsapp;
                }
                if (data.prefijo) {
                    prefijo = data.prefijo;
                }

                // Normalizar número (quitar no-dígitos, quitar ceros a la izquierda, agregar 591 si parece número local)
                if (toNumber) {
                    toNumber = String(toNumber).replace(/[^0-9]/g, '');
                    toNumber = toNumber.replace(/^0+/, '');
                    if (toNumber.length > 0 && toNumber.length <= 8) {
                        toNumber = prefijo + toNumber;
                    }
                }
                // Validar número
                if (!toNumber || !/^[0-9]{8,15}$/.test(toNumber)) {
                    alert('No se encontró un número de WhatsApp válido para enviar la comanda.');
                    return;
                }
                // listaProductos llega como string separado por ':'
                let detalles = '';
                if (typeof data.listaProductos === 'string' && data.listaProductos.length > 0) {
                    const items = data.listaProductos.split(':');
                    // Formato: id|cantidad|p_unit|importe|nota|p_base|importe_base|detalle
                    detalles = items.map((row, idx) => {
                        const cols = row.split('|');
                        const cant = cols[1] || '';
                        const detalle = cols[7] || '';
                        const nota = cols[4] ? ` (${cols[4]})` : '';
                        return `- ${cant} x ${detalle}${nota}`;
                    }).join('\n');
                }
                let totales = '';
                if (data.paymentDetails) {
                    var total = '';
                    if (data.paymentDetails.total_pagar !== undefined && data.paymentDetails.total_pagar !== null && data.paymentDetails.total_pagar !== '') {
                        total = data.paymentDetails.total_pagar;
                    } else if (data.paymentDetails.total !== undefined && data.paymentDetails.total !== null && data.paymentDetails.total !== '') {
                        total = data.paymentDetails.total;
                    }
                    if (total !== '') {
                        totales = `Total: ${total}`;
                    }
                }
                const body = [header, cliente, fecha, hora, 'Detalle:', detalles, '', totales]
                    .filter(Boolean)
                    .join('\n');
                const waUrl = `https://wa.me/${toNumber}?text=${encodeURIComponent(body)}`;
                window.open(waUrl, '_blank');
            } catch (e) {
                alert('Error al compartir por WhatsApp: ', e);
            }
        };
        
        pdfContainer.appendChild(closeBtn);
        pdfContainer.appendChild(printBtn);
        pdfContainer.appendChild(shareBtn);
        pdfContainer.appendChild(iframe);
        document.body.appendChild(pdfContainer);
    } else {
        // Si el contenedor ya existe, mostrarlo
        pdfContainer.style.display = 'flex';
    }
}

export function listOfProductsToString(listOfProducts){
    let listOfProductsString = "";
    let i = 0;
    listOfProducts.forEach(element => {
        if(i == listOfProducts.length-1){
            listOfProductsString = listOfProductsString+element.id_producto+"|"+element.cantidad+"|"+element.p_unit+"|"+element.importe+"|"+element.nota+"|"+element.p_base+"|"+element.importe_base+"|"+element.detalle
        }else{
            listOfProductsString = listOfProductsString+element.id_producto+"|"+element.cantidad+"|"+element.p_unit+"|"+element.importe+"|"+element.nota+"|"+element.p_base+"|"+element.importe_base+"|"+element.detalle+":" 
        }
        i++
    });
    return listOfProductsString;
}