export const progressMixin = {
  data() {
    return {
      progressDepth: 0,
    };
  },
  methods: {
    progressStart() {
      if (!this.$Progress) return;
      if (this.progressDepth === 0) {
        this.$Progress.start();
      }
      this.progressDepth++;
    },
    progressFinish() {
      if (!this.$Progress) return;
      this.progressDepth = Math.max(0, this.progressDepth - 1);
      if (this.progressDepth === 0) {
        this.$Progress.finish();
      }
    },
    progressFail() {
      if (!this.$Progress) return;
      this.progressDepth = Math.max(0, this.progressDepth - 1);
      if (this.progressDepth === 0) {
        this.$Progress.fail();
      }
    },
  },
};
